#include <math.h>
#define BASIC_IMPORT

int tld_shannon(double *vec, int n, double *entropy)
{
        double t = 0.0;
        double s = 0.0;
        ASSERT(vec != NULL, "No vector");
        ASSERT(n > 0, "Need at least one value");
        for(int i = 0; i < n;i++){
                ASSERT(vec[i] >= 0.0, "Value %d is negative or NaN", i);
                t += vec[i];
        }
        if(t == 0.0){
                *entropy = 0.0;
                return OK;
        }
        for(int i = 0; i < n;i++){
                if(vec[i]){
                        double p = vec[i] / t;
                        s += p * log2(p);
                }
        }

        s = s * -1.0;
        *entropy = s;
        return OK;
ERROR:
        return FAIL;
}

int tld_mean(double *vec, int n, double *mean)
{
        ASSERT(vec != NULL, "No vector");
        ASSERT(n > 0, "Need at least one value");
        double m = 0.0;
        for(int i = 0; i < n;i++){
                m += vec[i];
        }
        m /= (double) n;
        /* LOG_MSG("Mean: %f",m); */
        *mean = m;
        return OK;
ERROR:
        return FAIL;
}

int tld_pop_variance(double *vec, int n, double *variance)
{
        ASSERT(vec != NULL, "No vector");
        double m = 0.0;
        double v = 0.0;
        RUN(tld_mean(vec, n, &m));
        v = 0.0;
        for(int i = 0; i < n;i++){
                v += pow(vec[i] - m, 2.0);
        }
        v /= (double) n;
        *variance = v;
        return OK;
ERROR:
        return FAIL;
}

int tld_sample_variance(double *vec, int n, double *variance)
{
        ASSERT(vec != NULL, "No vector");
        ASSERT(n > 1, "Sample variance needs at least two values");
        double m = 0.0;
        double v = 0.0;
        RUN(tld_mean(vec, n, &m));
        v = 0.0;
        for(int i = 0; i < n;i++){
                v += pow(vec[i] - m, 2.0);
        }
        v /= (double) (n-1);
        *variance = v;
        return OK;
ERROR:
        return FAIL;
}

int tld_standardise(double *vec, int n, double *mean, double *stdev)
{
        double m;
        double variance;
        double s;

        RUN(tld_mean(vec, n, &m));
        RUN(tld_sample_variance(vec, n, &variance));

        s = sqrt(variance);
        if(s == 0.0){
                ERROR_MSG("Standard deviation is zero!");
        }
        for(int i = 0; i < n;i++){
                vec[i] = (vec[i] -m) / s;
        }

        *mean = m;
        *stdev = s;
        return OK;
ERROR:
        return FAIL;
}

int tld_sample_covariance(double *vec_a, double *vec_b, int n, double *cov)
{
        double mean_a;
        double mean_b;
        double c;
        ASSERT(n > 1, "Sample covariance needs at least two values");
        RUN(tld_mean(vec_a, n, &mean_a));
        RUN(tld_mean(vec_b, n, &mean_b));

        c = 0.0;
        for(int i = 0; i < n; i++){
                c += (vec_a[i] - mean_a) * (vec_b[i] - mean_b);
        }
        c = c / (double) (n-1);

        *cov = c;
        return OK;
ERROR:
        return FAIL;
}

int tld_pop_covariance(double *vec_a, double *vec_b, int n, double *cov)
{
        double mean_a;
        double mean_b;
        double c;
        RUN(tld_mean(vec_a, n, &mean_a));
        RUN(tld_mean(vec_b, n, &mean_b));

        c = 0.0;
        for(int i = 0; i < n; i++){
                c += (vec_a[i] - mean_a) * (vec_b[i] - mean_b);
        }
        c = c / (double) n;

        *cov = c;
        return OK;
ERROR:
        return FAIL;
}

int tld_pearson_corr(double *vec_a, double *vec_b, int n, double *corr)
{
        double var_a;
        double var_b;

        double cov;
        double c;
        RUN(tld_pop_variance(vec_a, n, &var_a));
        RUN(tld_pop_variance(vec_b, n, &var_b));

        RUN(tld_pop_covariance(vec_a, vec_b, n, &cov));

        c = sqrt(var_a * var_b);
        if(c == 0){
                c = 0;
        }else{
                c = cov / c;
        }

        *corr = c;
        return OK;
ERROR:
        return FAIL;
}

int tld_normal_pdf(double x, double mu, double sigma, double* p)
{
        double z;
        ASSERT(sigma > 0.0, "stdev must be positive.");
        z = (x - mu) / sigma;

        *p = exp(-z*z*0.5) / (sigma * sqrt(2. * 3.14159265358979323846264338328));

        return OK;
ERROR:
        return FAIL;
}

int tld_sigmoid(double x, double *out)
{
        double y;

        ASSERT(isinf(x) == 0, "x is infinite");
        ASSERT(isnan(x) == 0, "x is Nan");
        if(x < 0.0){
                y = exp(x);
                y = y / (1.0 + y);
        }else{
                y = 1.0 / (1.0 + exp(-1.0 * x));
        }
        *out = y;
        return OK;
ERROR:
        return FAIL;
}


int tld_sigmoid_safe(double x, double *out)
{
        // Define truncation limits based on double-precision floating point
        const double MAX_X = 709.782712893384;   // Approximately log(DBL_MAX)
        const double MIN_X = -709.782712893384;  // Approximately log(DBL_MIN)
        double y;
        // Handle NaN
        if(isnan(x)){
                y = NAN;
                *out = y;
                return OK;
                /* return NAN; */
        }

        // Handle positive and negative infinity
        if(isinf(x)){
                if (x > 0){
                        y = 1.0;
                        *out = y;
                        return OK;

                }else{
                        y = 0.0;
                        *out = y;
                        return OK;
                }
        }

        // Truncate x to prevent overflow
        if(x > MAX_X){
                y = 1.0;
                *out = y;
                return OK;
        }else if(x < MIN_X){
                y = 0.0;
                *out = y;
                return OK;
        }

        // Compute sigmoid in a numerically stable way

        if(x < 0.0){
                y = exp(x);
                y = y / (1.0 + y);
        }else{
                y = 1.0 / (1.0 + exp(-x));
        }
        *out = y;
        return OK;
}
