#include <math.h>
#include <float.h>
#include <stdint.h>
/*
  adopted from:

  https://metacpan.org/release/JANERT/Statistics-KernelEstimation-0.05/source/lib/Statistics/KernelEstimation.pm
*/
static int copy_steps(double *data, int data_len, double ***ret);
static int create_steps(double *data, int data_len, int n_steps, double band, double*** ret);
static int default_bandwidth(double *x,double* cnt, int len, double* band);


int tld_kde_pdf(double *data, int data_len, int n_steps, double ***out)
{
        double total_cnt = 0.0;
        double band = 0.1;

        double** ladder = NULL;

        ASSERT(data != NULL, "No data");
        ASSERT(data_len > 0,"No data len?");
        ASSERT(n_steps > 0,"Number of steps must be positive");

        RUN(default_bandwidth(data,NULL,data_len,&band));

        RUN(create_steps(data,data_len, n_steps, band, &ladder));

        total_cnt = data_len;

        for(int i = 0; i < n_steps;i++){
                double d = 0.0;

                for(int j = 0; j < data_len; j++){
                        double add_d = 0.0;
                        RUN(tld_normal_pdf(ladder[i][0], data[j], band,&add_d));
                        d+= add_d;
                }
                d  = d / total_cnt;
                ladder[i][1] = d;
        }

        *out = ladder;

        return OK;
ERROR:
        if(ladder){
                gfree(ladder);
        }
        return FAIL;
}

int tld_kde_count_pdf(double *data,double* cnt, int data_len, double*** out)
{
        double total_cnt = 0.0;
        double band = 0.1;

        double** ladder = NULL;

        ASSERT(data != NULL, "No data");
        ASSERT(cnt != NULL, "No counts");
        ASSERT(data_len > 0,"No data len?");

        total_cnt = 0.0;
        for(int i = 0; i < data_len; i++){
                ASSERT(cnt[i] >= 0.0, "Count %d is negative or NaN", i);
                total_cnt += cnt[i];
        }
        ASSERT(total_cnt > 0.0, "Total count is zero");

        RUN(copy_steps(data,data_len, &ladder ));

        RUN(default_bandwidth(data,cnt,data_len,&band));

        for(int i = 0; i < data_len;i++){
                double d = 0.0;

                for(int j = 0; j < data_len; j++){
                        double add_d = 0.0;
                        RUN(tld_normal_pdf(ladder[i][0], data[j], band,&add_d));
                        add_d = add_d * cnt[j];
                        d+= add_d;
                }
                d  = d / total_cnt;
                ladder[i][1] = d;
        }

        *out = ladder;

        return OK;
ERROR:
        if(ladder){
                gfree(ladder);
        }
        return FAIL;
}

int copy_steps(double *data, int data_len, double ***ret)
{
        double** x = NULL;
        galloc(&x, data_len,2);

        for(int i = 0; i < data_len;i++){
                x[i][0] = data[i];
                x[i][1] = 0.0;
        }
        *ret = x;
        return OK;
ERROR:
        if(x){
                gfree(x);
        }
        return FAIL;
}

/* Evaluation points: n_steps bin centres spanning [min, max]. When all
   data are equal the range is empty, so span mean +/- 4 bandwidths. */
int create_steps(double *data, int data_len, int n_steps, double band, double*** ret)
{
        double** x = NULL;
        double min = DBL_MAX;
        double max = -DBL_MAX;
        double step = 0.0;
        for(int i = 0;i < data_len;i++){
                if(max < data[i]){
                        max = data[i];
                }
                if(min > data[i]){
                        min = data[i];
                }
        }
        if(!(max > min)){
                min = min - 4.0 * band;
                max = max + 4.0 * band;
        }
        step = (max- min)  / (double)(n_steps);
        galloc(&x, n_steps,2);

        for(int i = 0; i < n_steps;i++){
                x[i][0] = min + (double) i * step + step / 2.0;
                x[i][1] = 0.0;
        }
        *ret = x;
        return OK;
ERROR:
        if(x){
                gfree(x);
        }
        return FAIL;

}

/* Silverman-style bandwidth sigma * (3n/4)^(-1/5). The variance is
   computed in two passes (mean first, then squared deviations) to avoid
   the cancellation of E[x^2] - E[x]^2 for data with a large offset. For
   constant data the bandwidth falls back to 1e-3 * |mean|, or 1.0 when
   the mean is zero. */
int default_bandwidth(double *x,double* cnt, int len, double* band)
{
        double sum_x = 0.0;
        double sum_dd = 0.0;
        double mean;
        double var;
        double sigma;
        double sum = 0.0;
        double b;

        for(int i = 0; i < len; i++){
                double w = cnt ? cnt[i] : 1.0;
                sum_x += w * x[i];
                sum += w;
        }
        ASSERT(sum > 0.0, "Total weight is zero");
        mean = sum_x / sum;
        ASSERT(isfinite(mean), "Data contain NaN or infinite values");

        for(int i = 0; i < len; i++){
                double w = cnt ? cnt[i] : 1.0;
                double d = x[i] - mean;
                sum_dd += w * d * d;
        }
        var = sum_dd / sum;
        if(!(var > 0.0)){
                var = 0.0;
        }
        sigma = sqrt(var);

        b = sigma * pow(3.0 * sum / 4.0 , -1.0 / 5.0 );
        if(!(b > 0.0)){
                b = fabs(mean) * 1e-3;
                if(!(b > DBL_MIN)){
                        b = 1.0;
                }
        }
        ASSERT(isfinite(b), "Bandwidth is not finite");
        *band = b;
        return OK;
ERROR:
        return FAIL;
}
/* ---- src/stats/norm_quantile.c ---- */

#include <math.h>

typedef struct {
        double v;
        int idx;
} n_itm;

static int cmp_n_itm (const void *a, const void *b);

/* Quantile normalisation of the m columns of an n x m matrix (in place).
   The reference distribution is the mean over columns of the sorted
   values. Each group of tied values in a column covers a run of sorted
   positions and gets the mean of the reference values over that run. */
int norm_quantile(double **data, int n, int m)
{
        double** data_rank = NULL;
        n_itm** l = NULL;

        double sum = 0.0;

        ASSERT(data != NULL, "No data");
        ASSERT(n > 0, "Need at least one row");
        ASSERT(m > 0, "Need at least one column");

        for(int i = 0; i < n; i++){
                for(int j = 0; j < m; j++){
                        ASSERT(!isnan(data[i][j]), "NaN at row %d column %d", i, j);
                }
        }

        galloc(&data_rank,n,m);
        MMALLOC(l, sizeof(n_itm*) * n );
        for(int i = 0; i < n;i++){
                l[i] = NULL;
        }
        for(int i = 0; i < n;i++){
                MMALLOC(l[i], sizeof(n_itm));
                l[i]->v = 0.0;
                l[i]->idx = 0;
        }

        /* Sorted values of each column */
        for(int column = 0; column < m; column++){
                for(int i = 0; i < n; i++){
                        l[i]->idx = i;
                        l[i]->v = data[i][column];
                }
                qsort(l,n,  sizeof(n_itm*), cmp_n_itm);

                for(int i = 0;i < n;i++){
                        data_rank[i][column] = l[i]->v;
                }
        }

        /* Reference quantiles: mean across columns at each sorted position */
        for(int i = 0; i < n;i++){
                sum = 0.0;
                for(int j = 0; j < m;j++){
                        sum += data_rank[i][j];
                }
                sum /= (double) m;
                data_rank[i][0] = sum;
        }

        for(int column = 0; column < m; column++){
                for(int i = 0; i < n; i++){
                        l[i]->idx = i;
                        l[i]->v = data[i][column];
                }
                qsort(l,n,  sizeof(n_itm*), cmp_n_itm);

                int start = 0;
                while(start < n){
                        int end = start + 1;
                        while(end < n && l[end]->v == l[start]->v){
                                end++;
                        }
                        sum = 0.0;
                        for(int k = start; k < end; k++){
                                sum += data_rank[k][0];
                        }
                        sum /= (double) (end - start);
                        for(int k = start; k < end; k++){
                                data[l[k]->idx][column] = sum;
                        }
                        start = end;
                }
        }

        gfree(data_rank);
        for(int i = 0; i < n;i++){
                MFREE(l[i]);
        }
        MFREE(l);
        return OK;
ERROR:
        if(data_rank){
                gfree(data_rank);
        }
        if(l){
                for(int i = 0; i < n;i++){
                        if(l[i]){
                                MFREE(l[i]);
                        }
                }
                MFREE(l);
        }
        return FAIL;
}


int cmp_n_itm (const void *a, const void *b)
{
        n_itm * const *one = a;
        n_itm * const *two = b;
        if((*one)->v > (*two)->v){
                return 1;
        }else if((*one)->v < (*two)->v){
                return -1;
        }
        /* Equal values: order by original index so the sort is deterministic */
        if((*one)->idx > (*two)->idx){
                return 1;
        }else if((*one)->idx < (*two)->idx){
                return -1;
        }
        return 0;
}
/* ---- src/stats/auc.c ---- */



#include <float.h>
#include <math.h>

/* Unified Struct Definition */
struct auc_pt {
        double Y;
        double Y_hat;
};

static int auc_sweep(double *Y, double *Y_hat, int n, double *auc_out, double *thres_out);

/* Comparator function for qsort to sort in ascending order */
static int auc_pt_sort(const void *a, const void *b) {
        struct auc_pt * const *one = a;
        struct auc_pt * const *two = b;

        if ((*one)->Y_hat < (*two)->Y_hat) {
                return -1;
        } else if ((*one)->Y_hat > (*two)->Y_hat) {
                return 1;
        } else {
                return 0;
        }
}

/* Function to compute AUC and determine the best threshold */
int tld_auc(double *Y, double *Y_hat, int n, double *t, double *ret)
{
        double thres = 0.0;
        double auc = 0.0;
        RUN(auc_sweep(Y, Y_hat, n, &auc, &thres));
        *t = thres;
        *ret = auc;
        return OK;
ERROR:
        return FAIL;
}

int tld_auc_calculate(double *Y, double *Y_hat, int n, double *ret)
{
        double thres = 0.0;
        double auc = 0.0;
        RUN(auc_sweep(Y, Y_hat, n, &auc, &thres));
        *ret = auc;
        return OK;
ERROR:
        return FAIL;
}

/* The best threshold is the score closest to the (0,1) corner of the
   ROC curve; samples with Y_hat >= threshold are called positive. */
int tld_auc_best_threshold(double *Y, double *Y_hat, int n, double *best_threshold)
{
        double thres = 0.0;
        double auc = 0.0;
        RUN(auc_sweep(Y, Y_hat, n, &auc, &thres));
        *best_threshold = thres;
        return OK;
ERROR:
        return FAIL;
}

/* Sorts the scores, sweeps the ROC curve from the highest score down,
   accumulates the area with the trapezoidal rule (tied scores form one
   step) and records the score nearest to the (0,1) corner. */
int auc_sweep(double *Y, double *Y_hat, int n, double *auc_out, double *thres_out)
{
        struct auc_pt** l = NULL;
        double thres = 0.0;
        double auc = 0.0;
        double tpr = 0.0;
        double fpr = 0.0;
        double last_tpr = 0.0;
        double last_fpr = 0.0;
        double best_distance = INFINITY;
        int tp = 0;
        int fp = 0;
        int total_positive = 0;
        int total_negative = 0;

        ASSERT(n > 0, "TLD auc needs more than 0 datapoints");
        ASSERT(Y != NULL, "No labels");
        ASSERT(Y_hat != NULL, "No predictions");

        MMALLOC(l, sizeof(struct auc_pt*) * n);
        for(int i = 0; i < n; i++) {
                l[i] = NULL;
        }

        for(int i = 0; i < n; i++) {
                if(!(Y[i] >= 0.0 && Y[i] <= 1.0)) {
                        ERROR_MSG("label %d out of range: %f", i, Y[i]);
                }
                if(isnan(Y_hat[i])) {
                        ERROR_MSG("prediction %d is NaN", i);
                }
                MMALLOC(l[i], sizeof(struct auc_pt));
                l[i]->Y = Y[i];
                l[i]->Y_hat = Y_hat[i];
                if (Y[i] == 1.0) {
                        total_positive++;
                } else {
                        total_negative++;
                }
        }

        if(total_positive == 0 || total_negative == 0) {
                ERROR_MSG("AUC needs both classes (%d positive, %d negative)", total_positive, total_negative);
        }

        qsort(l, n, sizeof(struct auc_pt*), auc_pt_sort);

        for (int i = n - 1; i >= 0; i--) {
                if(l[i]->Y == 1.0){
                        tp++;
                } else {
                        fp++;
                }

                if(i == 0 || l[i]->Y_hat != l[i-1]->Y_hat){
                        tpr = (double)tp / (double)total_positive;
                        fpr = (double)fp / (double)total_negative;

                        auc += (fpr - last_fpr) * (tpr + last_tpr) / 2.0;

                        double distance = sqrt(fpr * fpr + (1.0 - tpr) * (1.0 - tpr));
                        if (distance < best_distance) {
                                best_distance = distance;
                                thres = l[i]->Y_hat;
                        }

                        last_tpr = tpr;
                        last_fpr = fpr;
                }
        }

        *auc_out = auc;
        *thres_out = thres;

        for(int i = 0; i < n; i++) {
                MFREE(l[i]);
        }
        MFREE(l);
        return OK;
ERROR:
        if(l){
                for(int i = 0; i < n; i++) {
                        if(l[i]){
                                MFREE(l[i]);
                        }
                }
                MFREE(l);
        }
        return FAIL;
}

/* ---- src/data/bitfield.c ---- */

#define BITS_W 64
#define BIT_SHIFT 6
#define BIT_MASK 0x3F

static inline int _tl_bitfield_popcount_branchless(uint64_t x);
/* Here is a piece of code to calculate the hamming distance
        between two bitfields using the popcount instruction
        available on most modern CPUs
 */

int tl_bitfield_hamming(tl_bitfield *b1, tl_bitfield *b2,tl_bitfield* mask, int32_t* dist)
{
        /* making sure the bitfields have the same length */
        if(b1->len != b2->len || b2->alloc_len < b1->alloc_len){
                ERROR_MSG("bitfields have different lengths");
        }
        int32_t len = b1->alloc_len;
        int32_t count = 0;
        if(mask == NULL){
                for(int i = 0; i <  len; i++){
                        count += _tl_bitfield_popcount_branchless(b1->m[i] ^ b2->m[i]);
                }
        }else{
                if(mask->len != b1->len || mask->alloc_len < len){
                        ERROR_MSG("mask and bitfields have different lengths");
                }
                for(int i = 0; i <  len; i++){
                        count += _tl_bitfield_popcount_branchless((b1->m[i] ^ b2->m[i]) & mask->m[i]);
                }
        }
        *dist = count;
        return OK;
ERROR:
        return FAIL;
}

/* here is an alternative implementation of popcountll using branchless code*/
int _tl_bitfield_popcount_branchless(uint64_t x)
{
        x = x - ((x >> 1) & 0x5555555555555555ULL);
        x = (x & 0x3333333333333333ULL) + ((x >> 2) & 0x3333333333333333ULL);
        x = (x + (x >> 4)) & 0x0F0F0F0F0F0F0F0FULL;
        x = x + (x >> 8);
        x = x + (x >> 16);
        x = x + (x >> 32);
        return x & 0x7F;
}

int tl_bitfield_or(tl_bitfield *b1, tl_bitfield *b2,tl_bitfield* ret)
{
        if(b1->len != b2->len){
                ERROR_MSG("bitfields have different lengths");
        }
        if(ret->len != b1->len){
                ERROR_MSG("bitfields have different lengths");
        }

        int32_t len = b1->alloc_len;

        for(int i = 0; i <  len; i++){
                ret->m[i] = b1->m[i] | b2->m[i];
        }
        return OK;
ERROR:
        return FAIL;
}


int tl_bitfield_set(tl_bitfield *b, int32_t index)
{
        if(index < 0 || index >= b->len){
                return FAIL;
        }
        b->m[index >> BIT_SHIFT] |= (1ULL << (index & BIT_MASK));
        return OK;
}

int tl_bitfield_get(tl_bitfield *b, int32_t index, uint8_t* bit)
{
        if(index < 0 || index >= b->len){
                return FAIL;
        }
        *bit = (b->m[index >> BIT_SHIFT] & (1ULL << (index & BIT_MASK))) != 0;
        return OK;
}

int tl_bitfield_clear(tl_bitfield *b, int32_t index)
{
        if(index < 0 || index >= b->len){
                return FAIL;
        }
        b->m[index >> BIT_SHIFT] &= ~(1ULL << (index & BIT_MASK));
        return OK;
}

int tl_bitfield_reset(tl_bitfield *b)
{
        memset(b->m, 0, b->alloc_len * sizeof(uint64_t));
        return OK;
}

int tl_bitfield_copy(tl_bitfield *dst, tl_bitfield *src)
{
        if(dst->len != src->len){
                ERROR_MSG("bitfields have different lengths");
        }
        memcpy(dst->m, src->m, src->alloc_len * sizeof(uint64_t));
        dst->len = src->len;
        dst->alloc_len = src->alloc_len;
        return OK;
ERROR:
        return FAIL;
}

int tl_bitfield_alloc(tl_bitfield **bit_f, int32_t size)
{
        tl_bitfield* b = NULL;
        MMALLOC(b, sizeof(tl_bitfield));
        b->alloc_len = 1 + size / BITS_W;
        galloc(&b->m, b->alloc_len);
        b->len = size;

        RUN(tl_bitfield_reset(b));
        *bit_f = b;
        return OK;
ERROR:
        tl_bitfield_free(b);
        return FAIL;
}

void tl_bitfield_free(tl_bitfield *b)
{
        if(b){
                if(b->m){
                        gfree(b->m);
                }
                free(b);
        }
}


